import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  Output,
} from '@angular/core';
import { PresentsetupService } from '../../../services/presentsetup/presentsetup.service';
import {
  presentListData,
  presentSetupData,
} from '../../../interfaces/presentsetup';
import { DatePipe } from '@angular/common';
import { ButtonComponent } from '../../../../shared/components/button/button.component';

@Component({
  selector: 'present-group',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ButtonComponent, DatePipe],
  templateUrl: './group.component.html',
  styleUrl: './group.component.scss',
})
export class GroupComponent {
  @Input() nCaseid: string;
  @Input() selectedUser: string[] = [];
  @Output() selectedUserChange = new EventEmitter<string[]>();
  @Input() cName: string;
  @Output() cNameChange = new EventEmitter<string>();

  @Input() presentData: presentSetupData;

  presetationList: presentListData[] = [];

  constructor(
    private readonly PSservice: PresentsetupService,
    private cdr: ChangeDetectorRef
  ) {}

  async ngOnInit() {

    this.presetationList = await this.PSservice.getPresentationList(
      this.nCaseid,
      this.presentData.nTypeid
    );
    this.cdr.detectChanges();
  }

  fillDetails(x: presentListData, clear: boolean) {
    this.resetSelection();

    if (clear) {
      this.selectedUser = [];
      this.cName = '';
      this.cNameChange.emit(this.cName);
      this.selectedUserChange.emit(this.selectedUser);

      return;
    }

    this.cName = x.cName;
    this.cNameChange.emit(this.cName);

    this.selectedUser = [...x.jUsers];
    this.selectedUserChange.emit(this.selectedUser);

    x.isSelected = true;
  }

  applyPresetation(x: presentListData) {
    this.resetSelection();

    this.cName = x.cName;
    this.cNameChange.emit(this.cName);

    this.selectedUser = [...x.jUsers];
    this.selectedUserChange.emit(this.selectedUser);

    x.isSelected = true;
    x.bIsApplied = true;
  }

  resetSelection() {
    this.presetationList.forEach((item) => {
      item.isSelected = false;
      item.bIsApplied = false;
    });
  }
}
